('game-changer','Game Changer','Goodpart',NULL,'{"slug":"game-changer","name":"Game Changer","author":"Goodpart","creator":"Goodpart","characters":["off-chef","off-highpriestess","off-sailor","off-balloonist","off-fortuneteller","mechanical-man","off-gambler","off-savant","off-philosopher","off-fisherman","off-juggler","off-ravenkeeper","off-poppygrower","thrall","off-drunk","missionary","off-barber","off-harpy","off-cerenovus","off-fearmonger","arbiter-the-menagerie","chatterpox","off-lilmonsta","off-vigormortis","off-lleech","off-barista","off-harlot","off-deviant","off-bishop","taxidermist-the-menagerie","off-bootlegger","peanut-gallery"],"synopsis":"A goofy script centered around the Chatterpox and the Arbiter - where the only way to learn is by playing, the only way to win is by learning, and the only way to stay alive is by following the rules. Or is it?\n\nThis script is for: People who enjoy the fun kind of chaos, and not taking the game too seriously while still having a puzzle to solve.","logo":"https://menagerie.towerrangers.net/images/logo/gclogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-barista","off-philosopher","off-poppygrower","chatterpox","off-sailor","off-lilmonsta","arbiter-the-menagerie","off-lleech","off-cerenovus","off-fearmonger","off-harpy","thrall","off-chef","off-fortuneteller","off-balloonist","mechanical-man","off-highpriestess"],"other":["off-barista","chatterpox","off-harlot","off-philosopher","off-poppygrower","off-sailor","off-gambler","off-cerenovus","arbiter-the-menagerie","thrall","off-vigormortis","off-harpy","off-fearmonger","off-lleech","off-lilmonsta","off-barber","mechanical-man","off-ravenkeeper","off-fortuneteller","off-juggler","off-balloonist","off-highpriestess"]}}','published',datetime('now'),datetime('now')),
('balance-in-all-things','Balance in All Things','Goodpart',NULL,'{"slug":"balance-in-all-things","name":"Balance in All Things","author":"Goodpart","creator":"Goodpart","characters":["off-washerwoman","off-librarian","off-pixie","off-empath","off-highpriestess","off-balloonist","off-flowergirl","off-exorcist","off-gossip","off-savant","off-seamstress","off-ravenkeeper","off-pacifist","stowaway-the-menagerie","off-plaguedoctor","off-hatter","off-mutant","yang","off-godfather","off-poisoner","off-witch","off-assassin","off-marionette","yin-yang","off-fanggu","yin","off-harlot","off-gunslinger","off-judge","off-bishop","taxidermist-the-menagerie","off-gardener","off-bootlegger"],"synopsis":"A script designed around the Yin and Yang. Find the Demon while keeping an eye on its good counterpart, lest it become evil - or worse.\n\nThis script is for: People who don''t mind living with the constant feeling that you''re about to turn evil at a moment''s notice. People who love a boss fight.","logo":"https://menagerie.towerrangers.net/images/logo/ballogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-marionette","yang","off-poisoner","off-godfather","off-witch","off-pixie","off-washerwoman","off-librarian","off-empath","off-seamstress","off-balloonist","off-highpriestess"],"other":["off-harlot","off-poisoner","off-witch","yang","yin-yang","yin","off-exorcist","off-fanggu","off-assassin","off-godfather","off-gossip","off-hatter","off-plaguedoctor","off-ravenkeeper","off-empath","off-flowergirl","off-seamstress","off-balloonist","off-highpriestess"]}}','published',datetime('now'),datetime('now')),
('belly-up','Belly Up','Goodpart',NULL,'{"slug":"belly-up","name":"Belly Up","author":"Goodpart","creator":"Goodpart","characters":["off-investigator","off-washerwoman","off-shugenja","off-chambermaid","off-dreamer","off-towncrier","off-oracle","off-gambler","off-gossip","off-alsaahir","off-fisherman","off-sage","off-mayor","stowaway-the-menagerie","off-tinker","off-moonchild","off-saint","off-mutant","off-cerenovus","lady-lace","off-marionette","off-wraith","off-scarletwoman","off-imp","off-vigormortis","polterghast","off-butcher","off-gunslinger","off-bonecollector","off-judge","off-voudon","off-gardener","off-bootlegger","peanut-gallery"],"synopsis":"A script designed to showcase the Polterghast. Maybe the Demon is dead - but maybe it''s just playing.\n\nThis script is for: People who like the idea of the Zombuul, but want games to last for less than 15 days. Zombuul enjoyers, assemble.","logo":"https://menagerie.towerrangers.net/images/logo/bellogo.png","almanac":"","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-wraith","off-marionette","lady-lace","off-cerenovus","off-washerwoman","off-investigator","off-dreamer","off-shugenja","off-chambermaid"],"other":["off-wraith","off-bonecollector","lady-lace","off-gambler","off-cerenovus","off-scarletwoman","polterghast","off-imp","off-vigormortis","off-gossip","off-sage","off-tinker","off-moonchild","off-dreamer","off-towncrier","off-oracle","off-chambermaid"]}}','published',datetime('now'),datetime('now')),
('sweet-nothings','Sweet Nothings','Goodpart',NULL,'{"slug":"sweet-nothings","name":"Sweet Nothings","author":"Goodpart","creator":"Goodpart","characters":["off-knight","off-washerwoman","off-empath","off-highpriestess","off-villageidiot","off-dreamer","thaumaturge-the-menagerie","off-gambler","off-exorcist","mentalist-the-menagerie","off-nightwatchman","houndmaster","mime-the-menagerie","off-ogre","off-lunatic","off-recluse","off-damsel","off-godfather","off-devilsadvocate","saboteur-the-menagerie","wispr","off-yaggababble","off-ojo","baku-the-menagerie","off-barista","off-harlot","tactician-the-menagerie","off-bonecollector","off-scapegoat","off-bootlegger","peanut-gallery"],"synopsis":"A script designed around the Baku, Lost Lovers, and Mentalist. Get out there and talk to as many people as you can to help solve the game, but just know that you might be face to face with the Demon, keen to turn your information upside down.\n\nThis script is for: Talkers, yappers, and everyone inbetween. This script encourages interaction and conversation, as well as tracking who speaks to whom.","logo":"https://menagerie.towerrangers.net/images/logo/snlogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["thaumaturge-the-menagerie","off-barista","wispr","off-yaggababble","saboteur-the-menagerie","off-lunatic","off-godfather","off-devilsadvocate","off-damsel","off-washerwoman","off-empath","off-dreamer","off-knight","off-villageidiot","off-nightwatchman","off-ogre","off-highpriestess"],"other":["off-barista","thaumaturge-the-menagerie","tactician-the-menagerie","saboteur-the-menagerie","off-harlot","off-bonecollector","wispr","off-gambler","off-devilsadvocate","off-lunatic","off-exorcist","baku-the-menagerie","off-ojo","off-yaggababble","off-godfather","houndmaster","mime-the-menagerie","off-damsel","mentalist-the-menagerie","off-empath","off-dreamer","off-villageidiot","off-nightwatchman","off-highpriestess"]}}','published',datetime('now'),datetime('now')),
('are-we-the-bad-guys','Are We... the Bad Guys?','Goodpart',NULL,'{"slug":"are-we-the-bad-guys","name":"Are We... the Bad Guys?","author":"Goodpart","creator":"Goodpart","characters":["cartographer-the-menagerie","off-snakecharmer","off-dreamer","guardian-the-menagerie","off-flowergirl","prophet-the-menagerie","evangelist","disciple-the-menagerie","wire-tapper","houndmaster","mime-the-menagerie","off-sage","off-virgin","off-magician","off-lunatic","off-recluse","off-mutant","blasphemer","off-cerenovus","off-marionette","off-summoner","efreet","doppelganger-the-menagerie","seiren","off-imp","off-fanggu","off-barista","off-harlot","off-scapegoat","off-bishop","taxidermist-the-menagerie","off-bootlegger","peanut-gallery"],"synopsis":"A script where good is just a state of mind. You can never be sure if you''re good or evil - but if you are, you certainly can''t let anyone know it. Not yet, anyway.\n\nThis script is for: People who don''t mind suddenly playing for evil, and people who don''t mind selling out their evil team - maybe.","logo":"https://menagerie.towerrangers.net/images/logo/awtbglogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-barista","doppelganger-the-menagerie","wire-tapper","off-magician","off-lunatic","off-summoner","off-marionette","off-snakecharmer","seiren","off-cerenovus","guardian-the-menagerie","cartographer-the-menagerie","off-dreamer"],"other":["off-barista","off-harlot","efreet","off-snakecharmer","off-cerenovus","off-summoner","seiren","blasphemer","off-lunatic","off-imp","off-fanggu","guardian-the-menagerie","evangelist","disciple-the-menagerie","houndmaster","off-sage","mime-the-menagerie","prophet-the-menagerie","off-dreamer","off-flowergirl"]}}','published',datetime('now'),datetime('now')),
('resident-evil','Resident, Evil','Goodpart',NULL,'{"slug":"resident-evil","name":"Resident, Evil","author":"Goodpart","creator":"Goodpart","characters":["off-chef","off-investigator","old-sheriff","off-chambermaid","off-villageidiot","off-mathematician","off-cultleader","thaumaturge-the-menagerie","off-flowergirl","off-undertaker","off-philosopher","lost-lover","swindler-the-menagerie","stowaway-the-menagerie","off-klutz","off-saint","off-mutant","yang","blackmailer","off-pithag","off-baron","doppelganger-the-menagerie","off-lilmonsta","off-legion","patient-zero","off-thief","off-bureaucrat","off-barista","off-butcher","off-gunslinger","off-gardener","off-bootlegger","peanut-gallery"],"synopsis":"A script designed around Patient Zero and the Doppelganger. The Demon kills and poisons next to executees, but how do you know who''s sober, who''s an Outsider, who''s evil - and importantly, who''s who?\n\nThis script is for: People who don''t mind being in an Evil Twin pair. Kinda.","logo":"https://menagerie.towerrangers.net/images/logo/reslogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["thaumaturge-the-menagerie","off-barista","off-bureaucrat","off-thief","doppelganger-the-menagerie","off-philosopher","off-lilmonsta","yang","blackmailer","lost-lover","off-investigator","off-chef","old-sheriff","off-villageidiot","off-cultleader","off-chambermaid","off-mathematician"],"other":["off-barista","off-bureaucrat","thaumaturge-the-menagerie","off-pithag","swindler-the-menagerie","blackmailer","yang","off-thief","off-philosopher","patient-zero","off-legion","off-lilmonsta","lost-lover","off-undertaker","off-flowergirl","off-villageidiot","off-cultleader","off-chambermaid","off-mathematician"]}}','published',datetime('now'),datetime('now')),
('shadow-of-the-colossus','Shadow of the Colossus','Goodpart',NULL,'{"slug":"shadow-of-the-colossus","name":"Shadow of the Colossus","author":"Goodpart","creator":"Goodpart","characters":["off-chef","off-librarian","conspiracist-the-menagerie","off-balloonist","guardian-the-menagerie","dentist-the-menagerie","off-monk","off-gambler","off-huntsman","off-artist","shinkan","houndmaster","off-tealady","off-drunk","colossus","off-barber","off-damsel","off-godfather","off-poisoner","off-devilsadvocate","off-harpy","off-marionette","off-nodashii","off-imp","off-fanggu","off-harlot","off-butcher","off-gunslinger","off-bonecollector","off-judge","off-bootlegger","peanut-gallery"],"synopsis":"A script where the mighty Colossus takes over the town. Literally. Players next to the Colossus aren''t safe from the unfortunate title of Outsider - not even sober, healthy Townsfolk.\n\nThis script is for: People who love to puzzle out who the No Dashii has touched, and people who don''t mind seeing: \"You are the evil Fang Gu\".","logo":"https://menagerie.towerrangers.net/images/logo/collogo.png","almanac":"","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-marionette","off-poisoner","off-godfather","off-devilsadvocate","off-harpy","conspiracist-the-menagerie","off-huntsman","guardian-the-menagerie","off-damsel","off-librarian","off-chef","off-balloonist"],"other":["off-harlot","off-bonecollector","off-poisoner","off-gambler","off-monk","off-devilsadvocate","off-imp","dentist-the-menagerie","guardian-the-menagerie","off-harpy","off-fanggu","off-nodashii","shinkan","conspiracist-the-menagerie","houndmaster","off-godfather","off-barber","off-huntsman","off-damsel","off-balloonist"]}}','published',datetime('now'),datetime('now')),
('in-death-is-life','In Death - Is Life','Goodpart',NULL,'{"slug":"in-death-is-life","name":"In Death - Is Life","author":"Goodpart","creator":"Goodpart","characters":["off-noble","off-empath","off-balloonist","off-villageidiot","guardian-the-menagerie","off-oracle","dentist-the-menagerie","prophet-the-menagerie","off-seamstress","off-professor","martyr-the-menagerie","off-juggler","wire-tapper","off-recluse","missionary","off-sweetheart","off-zealot","off-godfather","blackmailer","off-cerenovus","necromancer-the-menagerie","off-marionette","off-shabaloth","off-vigormortis","off-lleech","off-bonecollector","off-scapegoat","off-bishop","off-voudon","taxidermist-the-menagerie","off-bootlegger","peanut-gallery"],"synopsis":"A script designed around death: who caused it, who prevented it, and who saw it coming. Features the Martyr, Necromancer, Guardian and Prophet.\n\nThis script is for: People who are happy to embody the phrase: \"death is not the end\"; people who like a good snipe.","logo":"https://menagerie.towerrangers.net/images/logo/indlogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["wire-tapper","off-marionette","blackmailer","off-lleech","off-godfather","off-cerenovus","guardian-the-menagerie","off-empath","off-seamstress","off-noble","off-balloonist","off-villageidiot"],"other":["off-bonecollector","off-cerenovus","martyr-the-menagerie","necromancer-the-menagerie","off-shabaloth","dentist-the-menagerie","blackmailer","guardian-the-menagerie","off-lleech","off-vigormortis","off-godfather","off-sweetheart","off-professor","prophet-the-menagerie","off-empath","off-oracle","off-seamstress","off-juggler","off-balloonist","off-villageidiot"]}}','published',datetime('now'),datetime('now')),
('tag-you-re-it','Tag, You''re It','Goodpart',NULL,'{"slug":"tag-you-re-it","name":"Tag, You''re It","author":"Goodpart","creator":"Goodpart","characters":["off-noble","off-clockmaker","off-highpriestess","off-preacher","off-snakecharmer","off-mathematician","off-towncrier","off-oracle","off-acrobat","off-savant","martyr-the-menagerie","evangelist","off-princess","disciple-the-menagerie","off-goon","off-drunk","stowaway-the-menagerie","off-saint","off-barber","off-poisoner","off-assassin","off-marionette","off-wraith","off-baron","off-ojo","off-po","umbra","off-bonecollector","off-judge","off-bishop","off-voudon","taxidermist-the-menagerie","off-gardener","off-bootlegger","peanut-gallery"],"synopsis":"A script designed around the terrifying Umbra, a hyper-mobile Demon who can swap place with evil Minions, and refresh their abilities in the process.\n\nThis script is for: Demon-hunters who don''t mind chasing rabbits down holes. Players who enjoy playing as evil, but don''t love the burden of playing a Demon that has to tough it out all game.","logo":"https://menagerie.towerrangers.net/images/logo/taglogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-wraith","off-marionette","off-preacher","off-poisoner","off-snakecharmer","off-clockmaker","off-noble","off-highpriestess","off-mathematician"],"other":["off-wraith","off-bonecollector","off-preacher","off-poisoner","umbra","evangelist","off-acrobat","off-princess","off-snakecharmer","off-ojo","off-po","martyr-the-menagerie","off-assassin","disciple-the-menagerie","off-barber","off-towncrier","off-oracle","off-highpriestess","off-mathematician"]}}','published',datetime('now'),datetime('now')),
('when-the-music-stops','When the Music Stops','Goodpart',NULL,'{"slug":"when-the-music-stops","name":"When the Music Stops","author":"Goodpart","creator":"Goodpart","characters":["off-chef","off-noble","off-highpriestess","off-fortuneteller","dentist-the-menagerie","off-gambler","off-savant","off-engineer","off-fisherman","off-farmer","off-sage","off-tealady","off-magician","off-drunk","off-recluse","off-barber","off-hatter","off-devilsadvocate","off-pithag","off-goblin","off-boffin","off-yaggababble","off-kazali","off-fanggu","off-barista","off-harlot","off-butcher","off-bonecollector","off-scapegoat","pyro","off-bootlegger"],"synopsis":"A script designed around the Loric character, the Pyro. Nominations? Who needs ''em? Turn your eyes to the skies and point at the pretty fireworks instead. But beware, because at the end of each day, someone''s liable to go boom.\n\nThis script is for: People who hate accusations, defense, pertinent statements, and putting hands up.","logo":"https://menagerie.towerrangers.net/images/logo/muslogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-kazali","off-barista","off-boffin","off-yaggababble","off-magician","off-engineer","off-devilsadvocate","off-chef","off-fortuneteller","off-noble","off-highpriestess"],"other":["off-barista","off-harlot","off-bonecollector","off-engineer","off-gambler","off-devilsadvocate","off-pithag","off-fanggu","off-yaggababble","off-kazali","dentist-the-menagerie","off-hatter","off-barber","off-sage","off-farmer","off-fortuneteller","off-highpriestess"]}}','published',datetime('now'),datetime('now')),
('tick-tock','Tick Tock','Goodpart',NULL,'{"slug":"tick-tock","name":"Tick Tock","author":"Goodpart","creator":"Goodpart","characters":["off-shugenja","conspiracist-the-menagerie","off-empath","off-highpriestess","guardian-the-menagerie","off-undertaker","off-monk","prophet-the-menagerie","off-artist","mortician","wire-tapper","off-farmer","off-virgin","record-keeper","missionary","off-barber","off-zealot","off-harpy","off-fearmonger","off-marionette","gerrymanderer","off-baron","off-nodashii","off-vortox","chronos","off-bureaucrat","off-harlot","off-beggar","off-scapegoat","taxidermist-the-menagerie","off-bootlegger","peanut-gallery"],"synopsis":"A script where information has the potential to go topsy-turvy every other night. Figure out whether information is correct or wrong to pin down the Demon and win the game.\n\nThis script is for: People who enjoy hearing \"is this a Vortox game?\" but don''t enjoy it when people are able to confirm it.","logo":"https://menagerie.towerrangers.net/images/logo/ticklogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-bureaucrat","wire-tapper","off-marionette","off-fearmonger","off-harpy","conspiracist-the-menagerie","guardian-the-menagerie","record-keeper","off-empath","off-shugenja","off-highpriestess"],"other":["off-bureaucrat","off-harlot","off-monk","record-keeper","off-fearmonger","off-harpy","gerrymanderer","chronos","off-nodashii","off-vortox","conspiracist-the-menagerie","guardian-the-menagerie","off-barber","mortician","prophet-the-menagerie","off-farmer","off-empath","off-undertaker","off-highpriestess"]}}','published',datetime('now'),datetime('now')),
('true-colours','True Colours','Goodpart',NULL,'{"slug":"true-colours","name":"True Colours","author":"Goodpart","creator":"Goodpart","characters":["off-clockmaker","off-empath","off-fortuneteller","chameleon-the-menagerie","off-oracle","off-innkeeper","gatekeeper-the-menagerie","off-fisherman","off-juggler","off-ravenkeeper","mime-the-menagerie","off-mayor","off-fool","off-ogre","off-plaguedoctor","off-moonchild","off-saint","off-poisoner","off-devilsadvocate","off-goblin","gerrymanderer","off-imp","off-vortox","hypnox","off-harlot","off-bonecollector","off-apprentice","off-deviant","off-bishop","off-bootlegger","peanut-gallery"],"synopsis":"A script designed around the Chameleon, whose powers change each night. With so many combinations and pairs of abilities, you''ll may never truly know whether you''re hurting or helping.\n\nThis script is for: Lovers of the Philosopher, and people who love to solve a puzzle, as long as they are the puzzle themselves.","logo":"https://menagerie.towerrangers.net/images/logo/truclogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-apprentice","chameleon-the-menagerie","off-poisoner","hypnox","off-devilsadvocate","off-empath","off-fortuneteller","off-clockmaker","off-ogre"],"other":["off-innkeeper","off-harlot","off-bonecollector","off-poisoner","off-devilsadvocate","chameleon-the-menagerie","gerrymanderer","hypnox","off-imp","off-vortox","gatekeeper-the-menagerie","off-plaguedoctor","mime-the-menagerie","off-moonchild","off-ravenkeeper","off-empath","off-fortuneteller","off-oracle","off-juggler"]}}','published',datetime('now'),datetime('now')),
('way-of-the-samurai','Way of the Samurai','Goodpart',NULL,'{"slug":"way-of-the-samurai","name":"Way of the Samurai","author":"Goodpart","creator":"Goodpart","characters":["banker-the-menagerie","off-shugenja","off-empath","guardian-the-menagerie","off-oracle","off-gambler","off-alsaahir","prophet-the-menagerie","off-philosopher","lost-lover","ronin-the-menagerie","shinkan","off-fool","off-drunk","off-moonchild","record-keeper","off-puzzlemaster","lady-lace","necromancer-the-menagerie","off-assassin","off-marionette","off-vizier","off-nodashii","off-lleech","polterghast","off-barista","off-butcher","off-bonecollector","off-scapegoat","taxidermist-the-menagerie","off-bootlegger","peanut-gallery"],"synopsis":"A script designed around the Ronin, who grows in power when their allied player is slain by the Demon. With some nights of no deaths, and some nights of many deaths, the Ronin is tasked with navigating many sources of death to win in the end.\n\nThis script is for: People who like \"swingy\" games, and those who don''t mind a bit of poisoning.","logo":"https://menagerie.towerrangers.net/images/logo/samlogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-barista","off-philosopher","off-marionette","lady-lace","off-lleech","ronin-the-menagerie","lost-lover","guardian-the-menagerie","banker-the-menagerie","off-empath","off-shugenja","off-vizier"],"other":["record-keeper","off-barista","off-bonecollector","off-philosopher","lady-lace","off-gambler","polterghast","necromancer-the-menagerie","off-nodashii","off-lleech","off-assassin","ronin-the-menagerie","shinkan","lost-lover","guardian-the-menagerie","prophet-the-menagerie","off-moonchild","off-empath","off-oracle"]}}','published',datetime('now'),datetime('now')),
