('who-do-you-think-you-are','Who Do You Think You Are?','Goodpart',NULL,'{"slug":"who-do-you-think-you-are","name":"Who Do You Think You Are?","author":"Goodpart","creator":"Goodpart","characters":["off-librarian","old-sheriff","off-balloonist","off-dreamer","off-fortuneteller","off-undertaker","off-lycanthrope","off-savant","off-juggler","off-amnesiac","off-ravenkeeper","mime-the-menagerie","off-mayor","egotist","off-drunk","stowaway-the-menagerie","off-golem","off-mutant","off-godfather","off-poisoner","off-cerenovus","off-wizard","off-yaggababble","abomination","off-fanggu","off-bureaucrat","off-barista","off-judge","off-deviant","off-bishop","off-bootlegger","peanut-gallery"],"synopsis":"It''s THE EGOTIST! This conceited Outsider drunks anyone who would dare accuse them of evil, and wouldn''t dare have themselves executed for another''s crimes. But they may just end up being the one who did it.\n\nThis script is for: People who love a bit of drama, and hate self-nominations.","logo":"https://menagerie.towerrangers.net/images/logo/whologo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["abomination","off-barista","off-bureaucrat","off-yaggababble","off-poisoner","off-wizard","off-godfather","off-cerenovus","off-amnesiac","off-librarian","off-fortuneteller","off-dreamer","old-sheriff","off-balloonist"],"other":["off-barista","off-bureaucrat","off-poisoner","off-wizard","off-cerenovus","off-lycanthrope","abomination","off-fanggu","off-yaggababble","off-godfather","mime-the-menagerie","off-amnesiac","off-ravenkeeper","off-fortuneteller","off-undertaker","off-dreamer","off-juggler","off-balloonist"]}}','published',datetime('now'),datetime('now')),
('wispr-in-the-wind','Wispr In The Wind','Goodpart',NULL,'{"slug":"wispr-in-the-wind","name":"Wispr In The Wind","author":"Goodpart","creator":"Goodpart","characters":["off-investigator","off-shugenja","off-empath","off-highpriestess","off-preacher","off-fortuneteller","off-cultleader","off-undertaker","lost-lover","off-fisherman","off-sage","off-tealady","off-virgin","off-plaguedoctor","off-barber","off-zealot","off-puzzlemaster","off-harpy","off-fearmonger","off-marionette","wispr","off-pukka","off-nodashii","off-imp","off-lordoftyphon","off-thief","off-bonecollector","off-judge","off-beggar","off-bishop","off-spiritofivory"],"synopsis":"A script designed around the Wispr, who can change the physical makeup of the Grimoire by secretly seating itself between others. Do you know who your neighbours are?\n\nThis script is for: People who like to solve a tricky puzzle, or people who enjoy playing chill Minions.","logo":"https://menagerie.towerrangers.net/images/logo/wislogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-lordoftyphon","off-thief","wispr","off-marionette","off-preacher","off-fearmonger","off-harpy","off-pukka","lost-lover","off-investigator","off-empath","off-fortuneteller","off-shugenja","off-cultleader","off-highpriestess"],"other":["off-thief","off-bonecollector","off-preacher","wispr","off-fearmonger","off-harpy","off-imp","off-pukka","off-nodashii","off-lordoftyphon","lost-lover","off-barber","off-plaguedoctor","off-sage","off-empath","off-fortuneteller","off-undertaker","off-cultleader","off-highpriestess"]}}','published',datetime('now'),datetime('now')),
('the-imperial-palace','The Imperial Palace','Goodpart',NULL,'{"slug":"the-imperial-palace","name":"The Imperial Palace","author":"Goodpart","creator":"Goodpart","characters":["off-chef","off-noble","off-grandmother","off-empath","off-general","off-towncrier","off-oracle","gatekeeper-the-menagerie","off-alsaahir","off-seamstress","off-artist","off-banshee","off-magician","off-recluse","off-saint","record-keeper","off-zealot","off-poisoner","off-goblin","off-boffin","off-baron","shogun-the-menagerie","off-thief","off-butcher","off-beggar","off-bishop","off-voudon","off-bootlegger"],"synopsis":"Turn Clocktower on its head with an outed Demon who kills indiscriminately! The Shogun doesn''t know its Minions, and kills during the day. Outpace the Shogun, eliminate its Minions, and sprint to the finish, but beware executing the Shogun until you''re certain!\n\nThis script is for: People who want a fast, swingy game with plenty of chaos, and people who don''t mind playing a stressful Demon.","logo":"https://menagerie.towerrangers.net/images/logo/implogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-thief","off-boffin","off-magician","off-poisoner","off-chef","off-empath","off-grandmother","off-seamstress","off-noble","off-general"],"other":["off-thief","off-poisoner","record-keeper","gatekeeper-the-menagerie","off-banshee","off-grandmother","off-empath","off-towncrier","off-oracle","off-seamstress","off-general"]}}','published',datetime('now'),datetime('now')),
('stayin-alive','Stayin'' Alive','Goodpart',NULL,'{"slug":"stayin-alive","name":"Stayin'' Alive","author":"Goodpart","creator":"Goodpart","characters":["off-chef","off-shugenja","off-empath","off-mathematician","off-fortuneteller","off-oracle","dentist-the-menagerie","off-monk","off-lycanthrope","off-savant","off-engineer","off-professor","off-farmer","off-drunk","off-recluse","off-golem","off-barber","off-poisoner","off-assassin","off-wraith","off-summoner","embalmer-the-menagerie","baku-the-menagerie","off-po","off-vigormortis","off-barista","mad-scientist","off-butcher","off-bonecollector","off-bootlegger"],"synopsis":"Who''s alive? Who''s dead? There''s no way to truly know with the Embalmer in play. Confirm deaths through other means - but with the Demon poisoning, corrupting information or just slaughtering en masse, if you aren''t careful, it may already be too late. You want the Barrow-Fog? We have a Barrow-Fog at home.\n\nThis script is for: Lovers of the Barrow-Fog, or haters of the Barrow-Fog.","logo":"https://menagerie.towerrangers.net/images/logo/endlogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-wraith","off-barista","off-summoner","off-engineer","off-poisoner","off-chef","off-empath","off-fortuneteller","off-shugenja","off-mathematician"],"other":["off-wraith","off-barista","off-bonecollector","off-engineer","off-poisoner","off-monk","embalmer-the-menagerie","off-summoner","baku-the-menagerie","off-lycanthrope","off-po","off-vigormortis","mad-scientist","off-assassin","dentist-the-menagerie","off-barber","off-professor","off-farmer","off-empath","off-fortuneteller","off-oracle","off-mathematician"]}}','published',datetime('now'),datetime('now')),
('switcheroo','Switcheroo','Goodpart',NULL,'{"slug":"switcheroo","name":"Switcheroo","author":"Goodpart","creator":"Goodpart","characters":["off-librarian","off-pixie","off-empath","off-mathematician","off-fortuneteller","off-gambler","off-lycanthrope","off-philosopher","swindler-the-menagerie","off-juggler","off-cannibal","houndmaster","off-virgin","off-plaguedoctor","off-barber","off-hatter","eccentric","off-godfather","off-harpy","counterfeiter","off-marionette","off-summoner","baku-the-menagerie","off-vortox","off-fanggu","off-barista","mad-scientist","off-butcher","off-bonecollector","taxidermist-the-menagerie","off-gardener","off-bootlegger"],"synopsis":"You feel a square token in the bag. Do you take it? The Eccentric is the Outsider nobody dares speak of, but many know of. Combined with the Counterfeiter, who can snoop at the Grimoire and change the state of the game, this script results in weird, wonderful game states where nothing is as it seems.\n\nThis script is for: Chaos goblins, rule breakers, and risk-takers.","logo":"https://menagerie.towerrangers.net/images/logo/swilogo.png","almanac":"https://menagerie.towerrangers.net","curata":false,"hideTitle":true,"bootlegger":["View running notes and homebrew almanac at menagerie.towerrangers.net"],"nightOrder":{"first":["off-barista","off-philosopher","off-summoner","off-marionette","off-godfather","counterfeiter","off-harpy","off-pixie","off-librarian","off-empath","off-fortuneteller","off-mathematician"],"other":["off-barista","off-bonecollector","off-philosopher","off-gambler","off-harpy","baku-the-menagerie","off-lycanthrope","counterfeiter","off-fanggu","off-vortox","off-summoner","mad-scientist","off-godfather","houndmaster","swindler-the-menagerie","off-hatter","off-barber","off-plaguedoctor","off-empath","off-fortuneteller","off-juggler","off-mathematician"]}}','published',datetime('now'),datetime('now'));